    "stem": "A 49-year-old man undergoes primary medical assessment at a community health center in Islamabad Capital Territory with clinical findings indicative of Placenta Previa Sudden Painless Bright Red Bleeding Strict Avoidance of Digital Vaginal Examination. Clinical examination and investigative review confirm avoiding digital disruption of low-lying placental cotyledons with urgent ultrasound confirmation. Vitals reveal blood pressure of 130/72 mm Hg, heart rate of 78/min, respiratory rate of 14/min, and temperature of 36.6C (98.0F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of placenta previa sudden painless bright red bleeding strict avoidance of digital vaginal examination. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
